<script setup lang="ts">
import {ref,watch,onMounted,onUnmounted,nextTick} from 'vue'
import {RouterLink} from 'vue-router'
import {cityStories} from '../../data/cityStories'
import EditorialPhoto from '../../components/home/EditorialPhoto.vue'
type City={slug:string;name:string}
type Value={textValue:string|null;numericValue:number|null;period:string;unit:string;scope:string;method:string;sourceTitle:string;sourceUrl:string;checkedAt:string}
type Row={code:string;name:string;kind:string;status:'COMPARABLE'|'DIFFERENT_PERIOD'|'INCOMPARABLE'|'MISSING';left:Value|null;right:Value|null}
const cities=ref<City[]>([]),left=ref('beijing'),right=ref('shanghai'),rows=ref<Row[]>([]),loading=ref(false),error=ref('')
const states={COMPARABLE:'同口径可比',DIFFERENT_PERIOD:'统计时期不同',INCOMPARABLE:'口径不足或不同，仅并列阅读',MISSING:'资料待补充'}
let controller:AbortController|undefined,observer:IntersectionObserver|undefined
async function load(){controller?.abort();const request=new AbortController();controller=request;loading.value=true;error.value='';rows.value=[]
try{if(!cities.value.length){const r=await fetch('/api/content/cities',{signal:request.signal});if(!r.ok)throw Error();cities.value=await r.json()}
const r=await fetch(`/api/content/compare?left=${encodeURIComponent(left.value)}&right=${encodeURIComponent(right.value)}`,{signal:request.signal});if(!r.ok)throw Error();rows.value=(await r.json()).metrics
await nextTick();observer?.disconnect();if(!matchMedia('(prefers-reduced-motion: reduce)').matches){observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer?.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.compare-section').forEach(e=>{e.classList.add('reveal');observer?.observe(e)})}
}catch(e){if(!request.signal.aborted)error.value='城市资料暂时无法加载，请检查服务后重试。'}finally{if(controller===request)loading.value=false}}
watch([left,right],()=>{controller?.abort();loading.value=false;rows.value=[];error.value=''})
onMounted(load);onUnmounted(()=>{controller?.abort();observer?.disconnect()})
const story=(slug:string)=>cityStories.find(s=>s.id===slug)
</script>
<template><main class="compare-page"><nav><RouterLink to="/">RentWise / 首页</RouterLink><RouterLink to="/explore">Explore</RouterLink><RouterLink to="/living">Living</RouterLink></nav><header><p>COMPARE / PLACES & POSSIBILITIES</p><h1>两座城市，两种日常。</h1><p>把生活的线索放在一起。没有总分，没有排名，只有值得继续了解的问题。</p></header><form @submit.prevent="load"><label>城市一<select v-model="left"><option v-for="c in cities" :key="c.slug" :value="c.slug" :disabled="c.slug===right">{{c.name}}</option></select></label><label>城市二<select v-model="right"><option v-for="c in cities" :key="c.slug" :value="c.slug" :disabled="c.slug===left">{{c.name}}</option></select></label><button :disabled="loading||left===right">{{loading?'读取中…':'查看生活图鉴'}}</button></form><nav class="dimensions" aria-label="六维导航"><a v-for="row in rows" :key="row.code" :href="'#'+row.code">{{row.name}}</a></nav><p v-if="loading" role="status">正在读取城市资料…</p><div v-if="error" role="alert"><p>{{error}}</p><button @click="load">重试</button></div><p v-if="!loading&&!error&&!rows.length">暂时没有指标资料。</p><Transition name="content" mode="out-in"><div :key="left+right"><section v-for="(row,index) in rows" :id="row.code" :key="row.code" class="compare-section" :class="row.code"><p>0{{index+1}} / {{states[row.status]}}</p><h2>{{row.name}}</h2><div class="pair"><article v-for="(side,n) in [row.left,row.right]" :key="n"><h3>{{cities.find(c=>c.slug===(n===0?left:right))?.name}}</h3><template v-if="side"><p v-if="side.textValue">{{side.textValue}}</p><strong v-if="side.numericValue!==null" class="number">{{side.numericValue}} {{side.unit}}</strong><meter v-if="row.status==='COMPARABLE'&&row.kind==='NUMBER'&&side.numericValue!==null&&side.numericValue>=0" min="0" :max="Math.max(Number(row.left?.numericValue),Number(row.right?.numericValue),1)" :value="side.numericValue" :aria-label="row.name"/><dl><dt>统计时期</dt><dd>{{side.period==='UNSPECIFIED'?'原资料未明确统计时期':side.period}}</dd><dt>单位 / 口径</dt><dd>{{side.unit}} / {{side.scope}} / {{side.method}}</dd></dl><a :href="side.sourceUrl" target="_blank" rel="noopener noreferrer">{{side.sourceTitle}} ↗</a><small>来源核验 {{side.checkedAt}}</small></template><p v-else class="missing">—<br>尚无已核验资料，不估算、不补零。</p><template v-if="row.code==='housing'&&story(n===0?left:right)?.image"><EditorialPhoto v-for="image in [story(n===0?left:right)!.image!]" :key="image.src" :src="image.src" :alt="image.alt" :width="image.width" :height="image.height" :author="image.author" :source="image.work" :license="image.license" :license-url="image.licenseUrl" :note="image.changes"/></template><RouterLink v-if="row.code==='culture'&&story(n===0?left:right)" :to="'/explore/stories/'+(n===0?left:right)">阅读这座城市的住宅故事 →</RouterLink></article></div><p v-if="row.code==='transport'">观察建议：以自己的起终点和出行时段核对路线，城市概况不代表个人通勤。</p><p v-if="row.code==='cost'">观察建议：先明确整租或合租、区域与面积，再比较同一统计口径。</p></section></div></Transition><footer>资料缺失不代表城市表现较差。历史建筑照片不代表全城住宅；本页不是迁居建议、房源搜索或城市排行榜。</footer></main></template>
<style scoped>
.compare-page{width:min(1200px,calc(100% - 40px));margin:auto;color:#252523}.compare-page nav{display:flex;flex-wrap:wrap;gap:24px;padding:20px 0}.compare-page a{color:inherit;text-underline-offset:5px}.compare-page header{padding:48px 0}.compare-page h1{font-size:clamp(34px,5vw,64px);font-weight:500}.compare-page h2{font-size:32px;font-weight:500}.compare-page p{line-height:1.9}form{display:flex;flex-wrap:wrap;gap:24px;align-items:end}label{display:grid;gap:8px}select,button{min-height:44px;padding:10px 18px;font:inherit;border:1px solid #aaa;background:#f7f6f2;border-radius:8px}button{cursor:pointer}.dimensions{position:sticky;top:0;background:#f7f6f2;z-index:2;border-bottom:1px solid #ccc}.dimensions a{padding:10px 0}.compare-section{padding:40px 0;border-bottom:1px solid #ccc;scroll-margin-top:130px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:40px}.pair article{min-width:0}h3{font-size:24px}.missing{font-size:22px;color:#747068}.number{font-size:48px;display:block}dl,small{font-size:12px;line-height:1.8}dd{margin:0 0 8px}small{display:block}.employment article{background:#eeece6;padding:24px}.transport article{border-left:2px solid #999;padding-left:20px}.housing :deep(img){max-height:360px;object-fit:contain}.reveal{opacity:0;transform:translateY(16px);transition:opacity .35s,transform .35s}.visible{opacity:1;transform:none}.content-enter-active{transition:opacity .2s}.content-enter-from{opacity:0}meter{width:100%;height:24px;animation:chart .4s ease-out;transform-origin:left}@keyframes chart{from{transform:scaleX(0)}to{transform:scaleX(1)}}footer{padding:40px 0;line-height:1.8}a:focus-visible,button:focus-visible,select:focus-visible{outline:2px solid #333;outline-offset:4px}@media(max-width:600px){.pair{grid-template-columns:1fr;gap:24px}.dimensions{gap:12px!important;font-size:12px}.compare-section{scroll-margin-top:160px}}@media(prefers-reduced-motion:reduce){.reveal{opacity:1;transform:none;transition:none}meter{animation:none}.content-enter-active{transition:none}}
</style>
<style>body:has(.compare-page){background:#f7f6f2}</style>
